#!/usr/bin/env python3
"""Pack props/ai-voice/assets/*.mp3 into props/voice-data.js
(window.VN_VOICE). Keys: "<scene>__<line>" -> "<scene>.<line>"."""
import base64
from pathlib import Path

HERE = Path(__file__).resolve().parent / "assets"
out = [
    "// Generated by ai-voice/make-voice-data.py — do not edit.",
    "// Sampled line voices keyed '<scene>.<line>'; engine plays via playVoiceFor.",
    "window.VN_VOICE = {",
]
total = 0
packed = 0
for f in sorted(HERE.glob("*.mp3")):
    key = f.stem.replace("__", ".")
    data = base64.b64encode(f.read_bytes()).decode()
    total += len(data)
    packed += 1
    # keys like "call_lin.0" are NOT valid unquoted JS identifiers — unquoted
    # keys here once broke the whole script block and silenced every voice
    out.append(f'  "{key}": \'data:audio/mpeg;base64,{data}\',')
out.append("};")
(HERE.parent.parent / "voice-data.js").write_text(
    "\n".join(out), encoding="utf-8"
)
print(f"voice-data.js written: {packed} lines, base64 payload ~{total // 1024} KB")
